#include "app/RootComponent.h"
namespace jeff::daw {RootComponent::RootComponent():audioBackend(engine),audioController(audioBackend),midiService(midiBackend,queue),transport(engine),mirror([this](auto&e){event(e);}){juce::PropertiesFile::Options o;o.applicationName="Jeff DAW Studio";o.filenameSuffix="settings";o.osxLibrarySubFolder="Application Support";properties.setStorageParameters(o);title.setText("Jeff DAW Studio — Jam Mode",juce::dontSendNotification);title.setFont(juce::FontOptions(24,juce::Font::bold));monitorTitle.setText("MIDI Activity",juce::dontSendNotification);monitor.setReadOnly(true);monitor.setMultiLine(true);monitor.setScrollbarsShown(true);for(auto*c:{(juce::Component*)&title,(juce::Component*)&status,(juce::Component*)&transport,(juce::Component*)&mirror,(juce::Component*)&monitorTitle,(juce::Component*)&monitor,(juce::Component*)&deviceCenter})addAndMakeVisible(*c);auto ready=audioController.configure({});midiService.refresh();auto saved=properties.getUserSettings()->getValue("midiDeviceId").toStdString();if(!saved.empty())midiService.connect(saved);else if(!midiService.devices().empty()){midiService.connect(midiService.devices()[0].stableId);properties.getUserSettings()->setValue("midiDeviceId",juce::String(midiService.devices()[0].stableId));}if(!midiService.devices().empty())mirrorModel.setProfile(profiles.match(midiService.devices()[0]).kind());deviceModel.setAudio(audioController.status(),audioController.message());deviceModel.setMidi(midiService.devices(),midiService.selectedDeviceIds());status.setText(ready?"Audio ready":"Set up audio & MIDI",juce::dontSendNotification);startTimerHz(60);}void RootComponent::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff101319));}void RootComponent::resized(){auto r=getLocalBounds().reduced(18);auto h=r.removeFromTop(40);title.setBounds(h.removeFromLeft(h.getWidth()*2/3));status.setBounds(h);transport.setBounds(r.removeFromTop(54));deviceCenter.setBounds(r.removeFromBottom(190));if(r.getWidth()>850){auto side=r.removeFromRight(300);monitorTitle.setBounds(side.removeFromTop(28));monitor.setBounds(side.reduced(4));mirror.setBounds(r.reduced(6));}else{auto bottom=r.removeFromBottom(130);monitorTitle.setBounds(bottom.removeFromTop(26));monitor.setBounds(bottom);mirror.setBounds(r);}}void RootComponent::event(const PerformanceEvent&e){mirrorModel.consume(e);monitorModel.append("Virtual Orba",e);if(e.type==PerformanceEventType::noteOn)engine.setAuditionNote(60+e.note,e.value);else if(e.type==PerformanceEventType::noteOff)engine.stopAuditionNote();}void RootComponent::timerCallback(){mirrorModel.consumePending(queue,512,[this](auto&e){monitorModel.append("MIDI Input",e);});mirrorModel.tick(juce::Time::currentTimeMillis());mirror.setSnapshot(mirrorModel.snapshot());juce::String s;for(auto&r:monitorModel.rows())s<<r<<juce::newLine;if(monitor.getText()!=s){monitor.setText(s,false);monitor.moveCaretToEnd();}midiService.refresh();deviceModel.setMidi(midiService.devices(),midiService.selectedDeviceIds());deviceModel.setDiagnostics(queue.droppedCount(),0);deviceCenter.setModel(deviceModel);}}
